import type { TroopAbilityDefinition } from '../types';

// See core-attacks/README.md: RM names the print melee attack pattern (unnamed in print);
// replaces Kingmaker's retired Strike-based Battle.
export const battle: TroopAbilityDefinition = {
  "slug": "battle",
  "name": "Battle",
  "img": "systems/pf2e/icons/actions/OneThreeActions.webp",
  "group": "core-attack",
  "troopAttackTemplate": "troop-battle",
  "source": "reignmaker",
  "system": {
    "actionType": {
      "value": "action"
    },
    "actions": {
      "value": null
    },
    "category": "offensive",
    "description": {
      "value": "<p>Battle is the troop's core melee attack. Every troop has its own named Battle attack, marked <strong>[Battle]</strong>, carrying its individual damage values.</p><p><strong>Frequency</strong> once per round</p><p><strong>Effect</strong> Spending 1 to 3 actions, the troop attacks each enemy in a 5-foot emanation. Each enemy takes the damage listed on the troop's [Battle] attack for the number of actions spent, with a basic Reflex save against the troop's Battle DC. An off-guard enemy takes a -2 circumstance penalty to this save.</p>"
    },
    "traits": {
      "value": [
        "attack"
      ]
    },
    "slug": "battle"
  }
};

