export const battlefieldMedicine: TroopAbilityDefinition = {
  "slug": "battlefield-medicine",
  "name": "Battlefield Medicine",
  "img": "systems/pf2e/icons/actions/TwoActions.webp",
  "group": "war-action",
  "tier": "tactical",
  "source": "reignmaker",
  "system": {
    "actionType": {
      "value": "action"
    },
    "actions": {
      "value": 2
    },
    "category": "defensive",
    "description": {
      "value": "<p><strong>Requirements</strong> The troop has the Combat Medics tactic.</p><p><strong>Effect</strong> The troop's medics patch up wounds mid-battle, using the Treat Wounds DCs and healing amounts. Target the troop itself or an adjacent allied troop. Choose a DC based on the troop's level: DC 15 (any level), DC 20 (level 5+), DC 30 (level 10+), or DC 40 (level 15+). Attempt a Medicine check against that DC.</p><p><strong>Critical Success</strong> The target regains 4d8 HP (DC 15), 4d8+10 HP (DC 20), 4d8+30 HP (DC 30), or 4d8+50 HP (DC 40).</p><p><strong>Success</strong> The target regains 2d8 HP (DC 15), 2d8+10 HP (DC 20), 2d8+30 HP (DC 30), or 2d8+50 HP (DC 40).</p><p><strong>Critical Failure</strong> The target takes 1d8 damage.</p><p>A troop treated this way can't be the target of this troop's Battlefield Medicine again for 1 hour.</p>"
    },
    "traits": {
      "value": [
        "healing",
        "infantry"
      ]
    },
    "slug": "battlefield-medicine"
  },
  "prerequisites": {
    "armyTypes": [
      "infantry"
    ],
    "minLevel": 6,
    "tactics": [
      "combat-medics"
    ]
  }
};

