/** Gold price of training a tactic. All even, so "half cost" is always exact. */
export const GRADE_COSTS: Record<TacticGrade, number> = { 1: 4, 2: 8, 3: 12 };

export type TacticAvailabilityStatus = 'available' | 'known' | 'missing-prereq';

export interface TacticAvailabilityRow {
  entry: TacticLadderEntry;
  status: TacticAvailabilityStatus;
  cost: number;
  /** Unsatisfied prerequisite slug — set only when status is 'missing-prereq'. */
  missing?: string;
}

/**
 * What Tactical Training may offer for one army. Both the dialog and the
 * `trainTactic` handler classify through here so an offer and its validation
 * can never disagree.
 *
 * `atCap` never changes a row's status: an army at its slot cap still trains,
 * releasing a tactic it already knows.
 */
export function tacticAvailability(options: {
  knownSlugs: Iterable<string>;
  trainedCount: number;
  capacity: number;
}): { rows: TacticAvailabilityRow[]; atCap: boolean } {
  const known = new Set(options.knownSlugs);

  const rows = TACTICS_LADDER
    .filter((entry) => entry.family !== LOGISTICS_SHELF)
    .map((entry): TacticAvailabilityRow => {
      const cost = GRADE_COSTS[entry.grade];
      if (known.has(entry.slug)) return { entry, status: 'known', cost };
      if (entry.requires && !known.has(entry.requires)) {
        return { entry, status: 'missing-prereq', cost, missing: entry.requires };
      }
      return { entry, status: 'available', cost };
    });

  return { rows, atCap: options.trainedCount >= options.capacity };
}

/**
 * doctrineAbilityMappings.ts
 *
 * Defines which abilities are granted to armies based on doctrine tier.
 * Abilities are automatically applied when doctrine thresholds are reached.
 */

import type { DoctrineType, DoctrineTier } from '../types/Doctrine';

/**
 * Configuration for a doctrine ability
 */
export interface DoctrineAbilityConfig {
  /** Unique identifier for this ability mapping */
  id: string;
  /** Display name */
