  }
];

/**
 * Get abilities for a specific doctrine
 */
export function getAbilitiesForDoctrine(doctrine: DoctrineType): DoctrineAbilityConfig[] {
  return DOCTRINE_ABILITY_MAPPINGS.filter(a => a.doctrine === doctrine);
}

/**
 * Get all abilities that should be active given current doctrine state
 */
export function getActiveAbilities(
  doctrineValues: Record<DoctrineType, number>,
  dominant: DoctrineType | null,
  getTierForValue: (value: number) => DoctrineTier,
  tierMeetsMinimum: (current: DoctrineTier, minimum: DoctrineTier) => boolean
): DoctrineAbilityConfig[] {
  return DOCTRINE_ABILITY_MAPPINGS.filter(ability => {
    const doctrineValue = doctrineValues[ability.doctrine] || 0;
    const currentTier = getTierForValue(doctrineValue);

    // Check if tier requirement is met
    if (!tierMeetsMinimum(currentTier, ability.tier)) {
      return false;
    }

    // Check if dominant requirement is met
    if (ability.requiresDominant && dominant !== ability.doctrine) {
      return false;
    }

    return true;
  });
}

/**
 * Slug used to identify doctrine-granted abilities on actors
 */
export const DOCTRINE_ABILITY_SLUG_PREFIX = 'doctrine-ability-';

/**
 * Generate the slug for a doctrine ability
 */
export function getDoctrineAbilitySlug(abilityId: string): string {
  return `${DOCTRINE_ABILITY_SLUG_PREFIX}${abilityId}`;
}

/**
 * Standard Troop Abilities Configuration
 *
 * PF2e troops have standard abilities that are automatically added when
 * a creature is marked as a troop. This file defines those abilities.
 *
 * Note: Form Up and Troop Movement are sourced from the ability registry
 * (`src/data/troopAbilities`) so they stay identical to the Tactics view; only
 * Troop Defenses is generated dynamically from the troop's HP thresholds.
 *
 * Immunities and area/splash weaknesses are NOT here — the CRISPR kernel derives them
 * from `isTroop` + level (`troopAdjusted`/`troopImmunities`/`troopWeaknesses`).
 *
 * @see src/services/troops/troopLoader.ts for JSON-based template loading
 */

import type { SpecialAbility } from '@crispr-logic';
import type { TroopThresholds } from '@crispr-logic';
import { TROOP_ABILITIES, type TroopAbilityDefinition } from '../data/troopAbilities';

/**
 * Template for standard troop abilities
 * These are added automatically when isTroop is enabled
 */
export interface TroopAbilityTemplate {
  name: string;
  actionType: 'action' | 'reaction' | 'free' | 'passive';
  actions?: 1 | 2 | 3;
  traits: string[];
  description: string;
  /** Function to generate description with thresholds */
  getDescription?: (thresholds: TroopThresholds) => string;
}

function toAbilityTemplate(def: TroopAbilityDefinition): TroopAbilityTemplate {
  return {
    name: def.name,
    actionType: def.system.actionType.value,
    actions: (def.system.actions.value ?? undefined) as 1 | 2 | 3 | undefined,
    traits: def.system.traits.value,
    description: def.system.description.value,
  };
}

/**
 * Standard troop abilities that are automatically added to all troops
 */
export const STANDARD_TROOP_ABILITIES: TroopAbilityTemplate[] = [
  toAbilityTemplate(TROOP_ABILITIES['form-up']),
  toAbilityTemplate(TROOP_ABILITIES['troop-movement']),
];

/**
 * Generate the Troop Defenses ability with threshold values
 */
export function getTroopDefensesAbility(thresholds: TroopThresholds): TroopAbilityTemplate {
  return {
    name: 'Troop Defenses',
    actionType: 'passive',
    traits: [],
    description: `<p><strong>Thresholds</strong> ${thresholds.threshold1} (${thresholds.squares.atThreshold1} squares), ${thresholds.threshold2} (${thresholds.squares.atThreshold2} squares)</p>`
  };
}

/**
 * The 'troop' trait is automatically added to all troops
 * This trait provides inherent benefits (can't be flanked, etc.)
 */
export const TROOP_TRAIT = 'troop';

function toSpecialAbility(id: string, t: TroopAbilityTemplate): SpecialAbility {
  return {
    id,
    name: t.name,
    description: t.description,
    actionType: t.actionType,
    actions: t.actions,
    traits: t.traits,
  };
}

/**
 * Generate all standard troop special abilities
 */
export function generateStandardTroopAbilities(thresholds: TroopThresholds): SpecialAbility[] {
  const [formUp, troopMovement] = STANDARD_TROOP_ABILITIES;
  return [
    toSpecialAbility(`troop-form-up-${Date.now()}`, formUp),
    toSpecialAbility(`troop-movement-${Date.now()}`, troopMovement),
    toSpecialAbility(`troop-defenses-${Date.now()}`, getTroopDefensesAbility(thresholds)),
  ];
}

/**
 * Check if an ability is a standard troop ability (by name)
 */
export function isStandardTroopAbility(abilityName: string): boolean {
  const standardNames = ['Form Up', 'Troop Movement', 'Troop Defenses'];
  return standardNames.includes(abilityName);
}

/**
 * Filter out standard troop abilities from a list
 * Used when disabling troop mode to remove auto-added abilities
 */
export function filterOutTroopAbilities(abilities: SpecialAbility[]): SpecialAbility[] {
  return abilities.filter(a => !isStandardTroopAbility(a.name));
}

/**
 * Ability item builder
 *
 * Builds PF2e `action`-type itemData objects from editor-side `SpecialAbility`
 * entries. Mirrors `strikeItemBuilder` for melee strikes. Used by both creature
 * creation (`_createCreatureActorInternal`) and the create-missing branch of
 * `updateAbilityItems`.
 *
 * If the ability's description contains scalable patterns (PF2e @Damage /
 * @Check enricher macros, or plain dice/DC patterns), the parsed
 * `descriptionTemplate` + `scalableValues` are stamped onto the item's
 * benchmark flag at create time. That makes the values available for tier
 * stepping in the editor UI and ensures `syncAbilityItemsForLevel` rescales
 * them when the creature's level changes.
 */

import type { SpecialAbility } from '@crispr-logic';
import { parseAbilityDescription } from '@crispr-logic';
import { ABILITY_BENCHMARK_KEY, ABILITY_BENCHMARK_SCOPE } from './constants';
import type { AbilityBenchmarkData } from './types';

const ACTION_ICONS: Record<SpecialAbility['actionType'], (actions?: 1 | 2 | 3) => string> = {
  action: (actions) =>
    actions === 3 ? 'systems/pf2e/icons/actions/ThreeActions.webp'
    : actions === 2 ? 'systems/pf2e/icons/actions/TwoActions.webp'
    : 'systems/pf2e/icons/actions/OneAction.webp',
  reaction: () => 'systems/pf2e/icons/actions/Reaction.webp',
  free: () => 'systems/pf2e/icons/actions/FreeAction.webp',
  passive: () => 'systems/pf2e/icons/actions/Passive.webp'
};

export function composeAbilityItemData(ability: SpecialAbility, level: number): any {
  const itemData: any = {
    name: ability.name,
    type: 'action',
    img: ACTION_ICONS[ability.actionType](ability.actions),
    system: {
      description: { value: ability.description },
      actionType: { value: ability.actionType },
      actions: { value: ability.actionType === 'action' ? (ability.actions ?? 1) : null },
      traits: { value: ability.traits || [] }
    }
  };

  // Parse the description and stamp scalable values onto the benchmark flag so
  // the editor can tier-step damage/DC and so syncAbilityItemsForLevel rescales
  // them on level change. Skip if there's nothing to scale.
  const parsed = parseAbilityDescription(ability.description, level);
  if (parsed.scalableValues.length > 0) {
    const benchmarkData: AbilityBenchmarkData = {
      descriptionTemplate: parsed.template,
      scalableValues: parsed.scalableValues,
      originalDescription: ability.description
    };
    itemData.flags = {
      [ABILITY_BENCHMARK_SCOPE]: {
        [ABILITY_BENCHMARK_KEY]: benchmarkData
      }
    };
  }

  return itemData;
}

// Army Actor Bridge: Foundry actor + folder + token IO for army units.
// Pure kingdom-data CRUD lives in ArmyRepository.

import { getPartyActor } from '../../stores/ActorStore.svelte';
import { getKingdomData, updateKingdom } from '../../stores/KingdomStore';
import type { Army } from '../../models/Army';
import type { KingdomData } from '../../models/KingdomData';
import { PLAYER_KINGDOM, type OwnershipValue } from '../../types/ownership';
import { logger } from '../../utils/Logger';
import { extractEquipmentType, getItemSlug, segmentsLostFromSlugs, EQUIPMENT_ITEM_SLUG_PREFIX, WANDERERS_SLUG, FORAGERS_SLUG, VOLUNTEERS_SLUG, type EquipmentType } from '../../utils/presentation';
import { actionDispatcher } from '../ActionDispatcher';
import { ensureArmyFactionFolder } from './armyFolders';
import { createEquipmentEffect } from '../commands/armies/armyCommands';
import { dispatchCommands } from '../commands/dispatchCommands';
import { KingdomSettings } from '../../api/foundry';
import { ensureFactionEffectOnActor, resolveFactionEffectInfo } from './factionEffect';
import { TROOP_ABILITIES } from '../../data/troopAbilities';
import { MODULE_ID } from '../../config/flagKeys';
import { CREATURE_DATA_KEY } from '../creatures/constants';
import { troopCloneArt } from '../troops/officialTroopArt';
import { CONDITION_DEFINITIONS, composeEffect, type ConditionSlug } from '../../execution/armies/conditionRegistry';
import { conditionBadge, isPersistedArmyCondition, readPersistedConditions } from './persistedConditions';

function tacticItemData(slug: string): any {
  const def = TROOP_ABILITIES[slug];
  if (!def) {
    throw new Error(`[ArmyActorBridge] Unknown tactic slug: ${slug}`);
  }
  return {
    name: def.name,
    type: 'action',
    img: def.img,
    system: structuredClone(def.system)
  };
}

function isTrainedTacticItem(item: any): boolean {
  return item.flags?.[MODULE_ID]?.trainedTactic === true;
}
import { armyTokenDisplayName, armyActorAlliance, allianceForLedBy, KINGDOM_TOKEN_PF2E_FLAGS } from './armyTokenAppearance';
import { armyLocationsFromKingdom, type ArmyLocation } from './ArmyLocation';

export type { ArmyLocation };

export class ArmyActorBridge {
  private ensureTroopTrait(data: any): void {
    data.system = data.system || {};
    data.system.traits = data.system.traits || {};
    const value: string[] = Array.isArray(data.system.traits.value) ? data.system.traits.value : [];
    if (!value.includes('troop')) value.push('troop');
    data.system.traits.value = value;
  }

  /**
   * Best-effort write of the faction banner effect onto the actor. Failures
   * are logged but do not abort the army-create flow.
   */
  private async applyFactionBanner(actorId: string, factionId: string, armyName: string): Promise<void> {
    const game = (globalThis as any).game;
    const actor = game?.actors?.get(actorId);
    if (!actor) {
      logger.warn(`[ArmyActorBridge] Could not find actor ${actorId} when applying faction banner to "${armyName}"`);
      return;
    }
    const kingdom = getPartyActor()?.getKingdomData();
    if (!kingdom) return;
    try {
      const info = resolveFactionEffectInfo(factionId, kingdom);
      await ensureFactionEffectOnActor(actor, info);
    } catch (error) {
      logger.error(`[ArmyActorBridge] Failed to apply faction banner to "${armyName}":`, error);
    }
  }

  /**
   * Refresh the faction banner effect on every army actor in the current
   * kingdom. Used as a periodic self-heal so a manually-deleted banner
   * comes back within one turn. Per-army errors are isolated.
   */
  async refreshAllFactionBanners(): Promise<{ refreshed: number; skipped: number }> {
    const game = (globalThis as any).game;
    const kingdom = getPartyActor()?.getKingdomData();
    if (!kingdom) {
      logger.warn('[ArmyActorBridge] refreshAllFactionBanners: no kingdom data');
      return { refreshed: 0, skipped: 0 };
    }

    let refreshed = 0;
    let skipped = 0;
    for (const army of kingdom.armies ?? []) {
      if (!army.actorId) { skipped++; continue; }
      const actor = game?.actors?.get(army.actorId);
      if (!actor) { skipped++; continue; }
      try {
        const info = resolveFactionEffectInfo(army.ledBy || PLAYER_KINGDOM, kingdom);
        await ensureFactionEffectOnActor(actor, info);
        refreshed++;
      } catch (error) {
        logger.error(`[ArmyActorBridge] Failed to refresh faction banner for "${army.name}":`, error);
        skipped++;
      }
    }
    logger.info(`[ArmyActorBridge] refreshAllFactionBanners: ${refreshed} refreshed, ${skipped} skipped`);
    return { refreshed, skipped };
  }

  /**
   * Create a new NPC actor by cloning a template actor (world or compendium).
   * Used when an army type has a `templateActorUuid` set — preserves the template's
   * items/abilities while overriding name, level, images, alliance and folder.
   */
  async createNPCActorFromTemplate(
    templateUuid: string,
    name: string,
    level: number,
    portraitImage?: string,
    tokenImage?: string,
    factionId?: string
  ): Promise<string> {
    const game = (globalThis as any).game;
    const fromUuid = (globalThis as any).fromUuid;
    if (!fromUuid) {
      throw new Error('Foundry fromUuid not available');
    }

    const template = await fromUuid(templateUuid);
    if (!template) {
      throw new Error(`Template actor not found: ${templateUuid}`);
    }
    if (template.type !== 'npc') {
      throw new Error(`Template actor must be an NPC: ${templateUuid}`);
    }

    const alliance = allianceForLedBy(factionId, getPartyActor()?.getKingdomData());

    // Clone the template's serialized data, then override Reignmaker-specific
    // bits. toObject() includes embedded items, which is what we want.
    const sourceData: any = template.toObject();
    delete sourceData._id;

    // A world troop picked as template may itself be a linked army; the clone
    // must not inherit its army linkage or linkExistingActor rejects it.
    delete sourceData.flags?.['pf2e-reignmaker']?.['army-metadata'];

    const folderId = await ensureArmyFactionFolder(factionId || PLAYER_KINGDOM);

    sourceData.name = name;
    sourceData.folder = folderId;
    sourceData.ownership = { default: CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER };

    // Keyed on `template.name` because `sourceData.name` is already the army's.
    const art = troopCloneArt(sourceData, template.name, { portraitImage, tokenImage });

    if (art.img) sourceData.img = art.img;

    sourceData.prototypeToken = {
      ...(sourceData.prototypeToken ?? {}),
      texture: {
        ...(sourceData.prototypeToken?.texture ?? {}),
        src: art.tokenSrc
      },
      displayName: sourceData.prototypeToken?.displayName ?? 30,
      actorLink: true
    };

    if (art.strategyTokenImage) {
      sourceData.flags ??= {};
      sourceData.flags[MODULE_ID] ??= {};
      sourceData.flags[MODULE_ID][CREATURE_DATA_KEY] ??= {};
      sourceData.flags[MODULE_ID][CREATURE_DATA_KEY].strategyTokenImage = art.strategyTokenImage;
    }

    // Keep the template's native level here. The caller rescales the clone to the
    // recruit level afterward (rescaleManagedActorToLevel), which needs the native
    // level/stats to reverse-engineer benchmarks for core/world troops.
    sourceData.system = sourceData.system ?? {};
    sourceData.system.details = {
      ...(sourceData.system.details ?? {}),
      alliance,
      publicNotes: sourceData.system.details?.publicNotes ?? `Kingdom Army Unit - Level ${level}`
    };

    this.ensureTroopTrait(sourceData);

    const newActor = await game.actors.documentClass.create(sourceData);
    if (!newActor?.id) {
      throw new Error(`Failed to clone template actor: ${name}`);
    }

    logger.info(`[ArmyActorBridge] Cloned template ${templateUuid} → "${name}" (${newActor.id})`);

    await this.applyFactionBanner(newActor.id, factionId ?? PLAYER_KINGDOM, name);

    return newActor.id;
  }

  /**
   * Add metadata flag to army actor for identification.
   */
  async addArmyMetadata(actorId: string, armyId: string, armyType?: string): Promise<void> {
    const game = (globalThis as any).game;
    const npcActor = game?.actors?.get(actorId);

    if (!npcActor) {
      throw new Error(`NPC actor not found: ${actorId}`);
    }

    const partyActor = getPartyActor();

    await npcActor.setFlag('pf2e-reignmaker', 'army-metadata', {
      armyId: armyId,
      armyType: armyType,
      kingdomActorId: partyActor?.id
    });
  }

  /**
   * Sync army data → linked NPC actor (name, level).
   */
  async syncArmyToActor(armyId: string): Promise<void> {
    const actor = getPartyActor();
    if (!actor) {
      throw new Error('No kingdom actor available');
    }

    const kingdom = actor.getKingdomData();
    if (!kingdom) {
      throw new Error('No kingdom data available');
    }

    const army = kingdom.armies?.find((a: Army) => a.id === armyId);
    if (!army) {
      throw new Error(`Army with ID ${armyId} not found`);
    }

    if (!army.actorId) {
      throw new Error(`Army ${armyId} has no linked actor`);
    }

    const game = (globalThis as any).game;
    const npcActor = game?.actors?.get(army.actorId);

    if (!npcActor) {
      throw new Error(`NPC actor not found: ${army.actorId}`);
    }

    await npcActor.update({
      name: army.name,
      'system.details.level.value': army.level
    });

    try {
      const info = resolveFactionEffectInfo(army.ledBy || PLAYER_KINGDOM, kingdom);
      await ensureFactionEffectOnActor(npcActor, info);
    } catch (error) {
      logger.error(`[ArmyActorBridge] Failed to refresh faction banner for "${army.name}":`, error);
    }
  }

  /**
   * Sync NPC actor data → kingdom army record (mirrors actor edits made on the sheet).
   */
  async syncActorToArmy(actorId: string): Promise<void> {
    const game = (globalThis as any).game;
    const npcActor = game?.actors?.get(actorId);

    if (!npcActor) {
      throw new Error(`NPC actor not found: ${actorId}`);
    }

    await updateKingdom((kingdom: KingdomData) => {
      const army = kingdom.armies?.find((a: Army) => a.actorId === actorId);
      if (army) {
        army.name = npcActor.name;
        army.level = npcActor.system?.details?.level?.value || army.level;
      } else {
        logger.warn(`[ArmyActorBridge] No army found for actor: ${actorId}`);
      }
    });
  }

  /**
   * Apply an army-equipment upgrade (armor/runes/weapons/equipment) to the
   * army actor. Creates the matching PF2e effect item; the createItem hook
   * mirrors the result onto kingdom data via syncActorEquipmentToArmy.
