  /**
   * Rebuild kingdom-side `army.demoralized` from the actor's `demoralized`
   * effect item. Treats the actor as the source of truth so that manual sheet
   * edits (e.g. left/right-click on the badge in the token HUD) propagate
   * back to kingdom data instead of leaving the Reignmaker UI stale.
   */
  async syncActorDemoralizedToArmy(actorId: string): Promise<void> {
    const game = (globalThis as any).game;
    const npcActor = game?.actors?.get(actorId);

    if (!npcActor) {
      logger.warn(`[ArmyActorBridge] Actor not found for demoralized sync: ${actorId}`);
