  /**
   * Rebuild kingdom-side `army.segmentsLost` from Trooper's Troop Reduced
   * effects on the actor. Trooper applies them when a troop crosses an HP
   * threshold on a tactical scene and syncs them back to the world actor, so
   * the actor is the source of truth here as it is for demoralized.
   */
  async syncActorSegmentsToArmy(actorId: string): Promise<void> {
