  /** Rewrite `army.conditions` from the actor's persisted condition and effect items. */
  async syncActorConditionsToArmy(actorId: string): Promise<void> {
    const game = (globalThis as any).game;
    const npcActor = game?.actors?.get(actorId);

    if (!npcActor) {
      logger.warn(`[ArmyActorBridge] Actor not found for condition sync: ${actorId}`);
      return;
    }

    const conditions = readPersistedConditions(npcActor);

    await updateKingdom((kingdom: KingdomData) => {
      const army = kingdom.armies?.find((a: Army) => a.actorId === actorId);
      if (army) {
        army.conditions = conditions;
      } else {
        logger.warn(`[ArmyActorBridge] No army found for condition sync: ${actorId}`);
      }
    });
  }

  /**
   * One pass over every linked army so records written before the mirror
   * existed carry their actor's conditions. Writes only when something differs.
   */
  async refreshAllConditionMirrors(): Promise<{ updated: number }> {
    const game = (globalThis as any).game;
    const kingdom = getPartyActor()?.getKingdomData();
    if (!kingdom) return { updated: 0 };

    const fresh = new Map<string, Army['conditions']>();
    for (const army of kingdom.armies ?? []) {
      const actor = army.actorId ? game?.actors?.get(army.actorId) : null;
      if (!actor) continue;
      const conditions = readPersistedConditions(actor);
      if (JSON.stringify(conditions) !== JSON.stringify(army.conditions)) fresh.set(army.id, conditions);
    }
    if (fresh.size === 0) return { updated: 0 };

    await updateKingdom((k: KingdomData) => {
      for (const army of k.armies ?? []) {
        const conditions = fresh.get(army.id);
        if (conditions) army.conditions = conditions;
      }
    });
    logger.info(`[ArmyActorBridge] refreshAllConditionMirrors: updated ${fresh.size} army record(s)`);
    return { updated: fresh.size };
  }

  /**
   * Push each record's mirrored state back onto its actor after a save import.
   * Records without a `conditions` field predate the mirror and are left alone,
   * apart from the demoralized counter, which every record carries.
   */
  async restoreArmyActorState(kingdom: KingdomData): Promise<{ restored: number; unlinked: number }> {
    const game = (globalThis as any).game;
    let restored = 0;
    let unlinked = 0;

    for (const army of kingdom.armies ?? []) {
      const actor = army.actorId ? game?.actors?.get(army.actorId) : null;
      if (!actor) {
        unlinked++;
        continue;
      }
      try {
        await this.restoreActorConditions(actor, army);
        restored++;
      } catch (error) {
        logger.error(`[ArmyActorBridge] Failed to restore conditions on "${army.name}":`, error);
      }
    }

    if (unlinked > 0) {
      logger.warn(`[ArmyActorBridge] restoreArmyActorState: ${unlinked} army record(s) have no actor in this world`);
    }
    return { restored, unlinked };
  }

  private async restoreActorConditions(actor: any, army: Army): Promise<void> {
    const items = Array.from(actor.items.values()) as any[];
    const wanted = new Map((army.conditions ?? []).map((c) => [c.slug, c.badge]));
    const kept = new Set<string>();
    const stale: string[] = [];

    if (army.conditions) {
      for (const item of items) {
        if (!isPersistedArmyCondition(item)) continue;
        const slug = getItemSlug(item);
        if (wanted.has(slug) && !kept.has(slug) && conditionBadge(item) === wanted.get(slug)) {
          kept.add(slug);
        } else {
          stale.push(item.id);
        }
      }
    }

    const demoralizedItems = items.filter((i) => i.type === 'effect' && getItemSlug(i) === 'demoralized');
    const demoralizedNow = demoralizedItems.length ? (conditionBadge(demoralizedItems[0]) ?? 0) : 0;
    const demoralizedWanted = army.demoralized ?? 0;
    if (demoralizedNow !== demoralizedWanted) stale.push(...demoralizedItems.map((i) => i.id));

    if (stale.length) await actor.deleteEmbeddedDocuments('Item', stale);

    const effects: any[] = [];
    for (const [slug, badge] of wanted) {
      if (kept.has(slug)) continue;
      const def = CONDITION_DEFINITIONS[slug as ConditionSlug];
      if (def?.itemType === 'effect') {
        effects.push(composeEffect(def, badge ?? 1));
      } else {
        await actor.increaseCondition(slug, badge === null ? {} : { value: badge });
      }
    }
    if (demoralizedNow !== demoralizedWanted && demoralizedWanted > 0) {
      effects.push(composeEffect(CONDITION_DEFINITIONS.demoralized, demoralizedWanted));
    }
    if (effects.length) await actor.createEmbeddedDocuments('Item', effects);
  }

  /**
   * Rebuild the kingdom-side tactic exemptions from the actor's items:
   * Wanderers → `exemptFromGarrison`, Foragers → `exemptFromFood`,
   * Volunteers → `exemptFromGold`. The tactic items own these flags: any
   * other write (setArmyWandering's immediate tracking update) is reasserted
   * from the item state here, so a linked actor's kingdom record can't drift.
   */
  async syncActorTacticExemptionsToArmy(actorId: string): Promise<void> {
    const game = (globalThis as any).game;
    const npcActor = game?.actors?.get(actorId);

    if (!npcActor) {
      logger.warn(`[ArmyActorBridge] Actor not found for tactic-exemption sync: ${actorId}`);
      return;
    }

    const slugs = new Set(
      Array.from(npcActor.items.values() as Iterable<any>).map((i: any) => getItemSlug(i))
    );
    const hasWanderers = slugs.has(WANDERERS_SLUG);

    await updateKingdom((kingdom: KingdomData) => {
      const army = kingdom.armies?.find((a: Army) => a.actorId === actorId);
      if (army) {
        army.exemptFromGarrison = hasWanderers;
        army.exemptFromFood = slugs.has(FORAGERS_SLUG);
        army.exemptFromGold = slugs.has(VOLUNTEERS_SLUG);
        if (hasWanderers) {
          army.turnsUnsupported = 0;
        }
      } else {
        logger.warn(`[ArmyActorBridge] No army found for tactic-exemption sync: ${actorId}`);
      }
    });
  }

  /**
   * Create a trained-tactic item on the actor, flagged so it counts against
   * the army's slot cap — the discriminator that separates a trained tactic
   * from the same slug baked free on the troop's stat block.
   */
  async applyTrainedTactic(actorId: string, slug: string): Promise<void> {
    const game = (globalThis as any).game;
    const npcActor = game?.actors?.get(actorId);
    if (!npcActor) {
      logger.warn(`[ArmyActorBridge] Actor not found for trained-tactic apply: ${actorId}`);
      return;
    }

    // Step-8 can replay a committed descriptor (cross-client apply, reload).
    // A second item would make the reverse sync count the slug twice and
    // strand the army one slot short of its real capacity.
    const alreadyTrained = Array.from(npcActor.items.values() as Iterable<any>).some(
      (i: any) => isTrainedTacticItem(i) && getItemSlug(i) === slug
    );
    if (alreadyTrained) return;

    const itemData = tacticItemData(slug);
    itemData.flags = { [MODULE_ID]: { trainedTactic: true } };
    await npcActor.createEmbeddedDocuments('Item', [itemData]);
  }

  /**
   * Remove a trained-tactic item by slug. Only flagged items are eligible —
   * an unflagged (baked) item with the same slug is a different thing and
   * must survive.
   */
  async removeTrainedTactic(actorId: string, slug: string): Promise<void> {
    const game = (globalThis as any).game;
    const npcActor = game?.actors?.get(actorId);
    if (!npcActor) {
      logger.warn(`[ArmyActorBridge] Actor not found for trained-tactic removal: ${actorId}`);
      return;
    }

    const toRemove = Array.from(npcActor.items.values() as Iterable<any>).filter(
      (i: any) => isTrainedTacticItem(i) && getItemSlug(i) === slug
    );
    if (toRemove.length === 0) return;

    await npcActor.deleteEmbeddedDocuments('Item', toRemove.map((i: any) => i.id));
  }

  /**
   * Rebuild kingdom-side `army.tactics` from the actor's flagged trained-
   * tactic items. Unflagged items (baked abilities) never touch the record —
   * mirrors syncActorEquipmentToArmy's self-heal shape.
   */
  async syncActorTrainedTacticsToArmy(actorId: string): Promise<void> {
    const game = (globalThis as any).game;
    const npcActor = game?.actors?.get(actorId);

    if (!npcActor) {
      logger.warn(`[ArmyActorBridge] Actor not found for trained-tactic sync: ${actorId}`);
      return;
    }

    const tactics = [...new Set(
      Array.from(npcActor.items.values() as Iterable<any>)
        .filter((i: any) => isTrainedTacticItem(i))
        .map((i: any) => getItemSlug(i))
    )];

    await updateKingdom((kingdom: KingdomData) => {
      const army = kingdom.armies?.find((a: Army) => a.actorId === actorId);
      if (army) {
        army.tactics = tactics;
      } else {
        logger.warn(`[ArmyActorBridge] No army found for trained-tactic sync: ${actorId}`);
      }
    });
  }

  /**
   * Grant or revoke the Wanderers tactic. The kingdom-side flag updates
   * unconditionally so actor-less armies stay trackable; when an actor is
   * linked, the tactic item is added/removed too, since the item state is
   * what syncActorTacticExemptionsToArmy reasserts on every item change.
   */
  async setArmyWandering(armyId: string, wandering: boolean): Promise<void> {
    const kingdom = getPartyActor()?.getKingdomData();
    const army = kingdom?.armies?.find((a: Army) => a.id === armyId);
    if (!army) throw new Error(`Army not found: ${armyId}`);

    await dispatchCommands('ArmyActorBridge.setArmyWandering', [
      { name: 'setArmyWandering', args: { armyId, wandering } },
    ]);

    if (!army.actorId) return;
    const game = (globalThis as any).game;
    const npcActor = game?.actors?.get(army.actorId);
    if (!npcActor) return;

    const existing = Array.from(npcActor.items.values() as Iterable<any>).filter(
      (i: any) => getItemSlug(i) === WANDERERS_SLUG
    );

    if (wandering && existing.length === 0) {
      await npcActor.createEmbeddedDocuments('Item', [tacticItemData(WANDERERS_SLUG)]);
    } else if (!wandering && existing.length > 0) {
      await npcActor.deleteEmbeddedDocuments('Item', existing.map((i: any) => i.id));
    }
  }

  /**
   * Stamp the record's tracked improvements (exemption tactics + trained
   * tactics + equipment) onto the army's linked actor. Additive: items the
   * actor already has — including ones the record doesn't know about — are
   * left alone; the item syncs mirror the combined result back to the
   * record. Core creature stats (HP, AC, strikes) are never touched.
   * Returns the number of items granted.
   */
  async pushTrackedImprovementsToActor(armyId: string): Promise<number> {
    const kingdom = getPartyActor()?.getKingdomData();
    const army = kingdom?.armies?.find((a: Army) => a.id === armyId);
    if (!army?.actorId) return 0;

    const game = (globalThis as any).game;
    const npcActor = game?.actors?.get(army.actorId);
    if (!npcActor) return 0;

    const slugs = new Set(
      Array.from(npcActor.items.values() as Iterable<any>).map((i: any) => getItemSlug(i))
    );

    const trackedTactics: Array<[boolean | undefined, string]> = [
      [army.exemptFromGarrison, WANDERERS_SLUG],
      [army.exemptFromFood, FORAGERS_SLUG],
      [army.exemptFromGold, VOLUNTEERS_SLUG]
    ];
    const missingExemptions = trackedTactics
      .filter(([tracked, slug]) => tracked && !slugs.has(slug))
      .map(([, slug]) => tacticItemData(slug));

    // A record slug the registry no longer ships is dropped, not thrown on:
    // this stamp is shared with the Update Map reconciler, where one stale
    // slug would otherwise abort the whole pass for every army.
    const unknownTactics = (army.tactics ?? []).filter((slug) => !TROOP_ABILITIES[slug]);
    if (unknownTactics.length > 0) {
      logger.warn(`[ArmyActorBridge] Skipping unknown tactic slug(s) on "${army.name}": ${unknownTactics.join(', ')}`);
    }

    const missingTrainedTactics = (army.tactics ?? [])
      .filter((slug) => !slugs.has(slug) && TROOP_ABILITIES[slug])
      .map((slug) => ({ ...tacticItemData(slug), flags: { [MODULE_ID]: { trainedTactic: true } } }));

    const missing = [...missingExemptions, ...missingTrainedTactics];
    if (missing.length > 0) {
      await npcActor.createEmbeddedDocuments('Item', missing);
    }

    let granted = missing.length;
    for (const [type, owned] of Object.entries(army.equipment ?? {})) {
      if (owned && !slugs.has(`${EQUIPMENT_ITEM_SLUG_PREFIX}${type}`)) {
        await this.applyArmyEquipment(army.actorId, type as EquipmentType);
        granted++;
      }
    }
    return granted;
  }

  /**
   * Regenerate every army-equipment effect from the canonical builder.
   * Effect items are stored data, so a shipped change to an equipment
   * rule shape (e.g. weapons moving from +1 die to a level-scaled flat
   * bonus) never reaches already-outfitted armies without this.
   */
  async refreshAllEquipmentEffects(): Promise<{ updated: number }> {
    const game = (globalThis as any).game;
    const kingdom = getPartyActor()?.getKingdomData();
    if (!kingdom) return { updated: 0 };

    let updated = 0;
    for (const army of kingdom.armies ?? []) {
      if (!army.actorId) continue;
      const actor = game?.actors?.get(army.actorId);
      if (!actor) continue;

      for (const item of actor.items) {
        const type = extractEquipmentType(item.system?.slug ?? '');
        if (!type) continue;

        const canonical = createEquipmentEffect(type, 1);
        // Compare source data, not prepared data — rule elements mutate on prep.
        const sourceRules = item._source?.system?.rules ?? item.system?.rules ?? [];
        if (
          item.name === canonical.name &&
          JSON.stringify(sourceRules) === JSON.stringify(canonical.system.rules)
        ) continue;

        try {
          await item.update({
            name: canonical.name,
            img: canonical.img,
            'system.rules': canonical.system.rules
          });
          updated++;
        } catch (error) {
          logger.error(`[ArmyActorBridge] Failed to refresh ${type} equipment on "${army.name}":`, error);
        }
      }
    }

    if (updated > 0) {
      logger.info(`[ArmyActorBridge] refreshAllEquipmentEffects: updated ${updated} effect(s)`);
    }
    return { updated };
  }

  /**
   * Rebuild kingdom-side army.equipment from the actor's `army-equipment-*`
   * effect items. Self-healing: any path that mutates the actor's items
   * (UI flow, manual sheet edit, macro) funnels through here, so kingdom
   * data stays consistent with actor truth.
   */
  async syncActorEquipmentToArmy(actorId: string): Promise<void> {
    const game = (globalThis as any).game;
    const npcActor = game?.actors?.get(actorId);

    if (!npcActor) {
      logger.warn(`[ArmyActorBridge] Actor not found for equipment sync: ${actorId}`);
      return;
    }

    const equipment: NonNullable<Army['equipment']> = {};
    for (const item of npcActor.items) {
      const type = extractEquipmentType(item.system?.slug ?? '');
      if (type) equipment[type] = true;
    }

    await updateKingdom((kingdom: KingdomData) => {
      const army = kingdom.armies?.find((a: Army) => a.actorId === actorId);
      if (army) {
        army.equipment = equipment;
      } else {
        logger.warn(`[ArmyActorBridge] No army found for equipment sync: ${actorId}`);
      }
    });
  }

