  // ─── Internal GM-only methods (called by socket handlers) ────────────

  /**
   * Place army token at an explicit pixel position on a scene.
   * GM-only; called by the placeArmyToken socket handler.
   */
  async _placeArmyTokenInternal(actorId: string, sceneId: string, x: number, y: number): Promise<void> {
    const game = (globalThis as any).game;
    const scene = game?.scenes?.get(sceneId);

    if (!scene) {
      throw new Error(`Scene not found: ${sceneId}`);
    }

    const actor = game?.actors?.get(actorId);
    if (!actor) {
      throw new Error(`Actor not found: ${actorId}`);
    }

    // Kingdom-map token image overrides the actor's prototype token. The
    // actor's prototype is the battle-map representation; armies can carry a
    // separate strategy-scene image set at recruit (from the army type) or
    // via the per-army override button.
    const kingdom = getPartyActor()?.getKingdomData();
    const army = kingdom?.armies?.find((a: Army) => a.actorId === actorId);
    const proto = actor.prototypeToken;
    const tokenImageSrc = army?.armyTokenImage
      || proto?.texture?.src
      || actor.img;

    const tokenData: Record<string, any> = {
      actorId: actorId,
      x: x,
      y: y,
      hidden: false,
      actorLink: true,
      flags: KINGDOM_TOKEN_PF2E_FLAGS,
      texture: {
        src: tokenImageSrc,
        scaleX: 1,
        scaleY: 1
      },
      displayName: armyTokenDisplayName()
    };

    // PF2e derives token disposition from actor alliance; stamp the actor
    // so the border color and party mechanics match faction standing.
    if (army) {
      const alliance = armyActorAlliance(army, kingdom);
      if ((actor.system?.details?.alliance ?? null) !== alliance) {
        await actor.update({ 'system.details.alliance': alliance });
      }
    }

    // Strategic-scene tokens are always one-hex. PF2e troop templates default
    // to gargantuan (4×4); on a strategy map every army takes one hex regardless
    // of the unit's literal scale.
    if (sceneId === KingdomSettings.getKingdomSceneId()) {
      tokenData.width = 1;
      tokenData.height = 1;
    }

    const createdTokens = await scene.createEmbeddedDocuments('Token', [tokenData]);
    const createdToken = createdTokens[0];

    const canvas = (globalThis as any).canvas;
    const gridSize = canvas?.grid?.size || 100;

    const widthPx = createdToken.width * gridSize;
    const heightPx = createdToken.height * gridSize;

    const centeredX = x - widthPx / 2;
    const centeredY = y - heightPx / 2;

    await createdToken.update({
      x: centeredX,
      y: centeredY
    });
  }

  /**
   * Update the texture on every kingdom-scene token for this actor.
   * GM-only; called by the syncArmyKingdomToken socket handler.
   *
   * `src === null` reverts the texture to the actor's prototype-token image
   * (the battle-map default). Passing the same src as the existing texture
   * is a no-op per token.
   */
  async _syncArmyKingdomTokenInternal(actorId: string, src: string | null): Promise<void> {
    const game = (globalThis as any).game;
    const scene = KingdomSettings.getKingdomScene();

    if (!scene) {
      logger.warn('[ArmyActorBridge] Cannot sync kingdom token - no kingdom scene configured');
      return;
    }

    const actor = game?.actors?.get(actorId);
    const fallbackSrc = actor?.prototypeToken?.texture?.src || actor?.img;
    const targetSrc = src ?? fallbackSrc;
    if (!targetSrc) return;

    // Identify tokens via two routes:
    //   (a) direct actorId match — the normal case for Reignmaker-placed tokens
    //   (b) actor's army-metadata flag points at the same army — survives an
    //       actor swap where the original actor was replaced by another
    //       Reignmaker-created army actor (e.g. unlink + recreate via the row's
    //       "+" button). Looking up the army id from the recorded actor's
    //       metadata flag keeps the sync working without rewriting the link.
    const ownerArmyId = actor?.getFlag?.('pf2e-reignmaker', 'army-metadata')?.armyId;

    const matchingTokens = scene.tokens.filter((token: any) => {
      if (token.actorId === actorId) return true;
      if (!ownerArmyId) return false;
      const tokenArmyId = token.actor?.getFlag?.('pf2e-reignmaker', 'army-metadata')?.armyId;
      return tokenArmyId === ownerArmyId;
    });

    if (matchingTokens.length === 0) {
      logger.warn(
        `[ArmyActorBridge] syncArmyKingdomToken: no kingdom-scene token found for actor ${actorId}` +
        (ownerArmyId ? ` (army ${ownerArmyId})` : '') +
        ` — image saved on the army record but no token to update on "${scene.name}".`
      );
      return;
    }

    const updates = matchingTokens
      .filter((token: any) => token.texture?.src !== targetSrc)
      .map((token: any) => ({ _id: token.id, 'texture.src': targetSrc }));

    if (updates.length === 0) return;

    await scene.updateEmbeddedDocuments('Token', updates);
    logger.info(`[ArmyActorBridge] Synced kingdom-token image for actor ${actorId} on ${updates.length} token(s)`);
  }

  /**
   * Remove all tokens for an army actor from all scenes.
   * GM-only; called by _disbandArmyInternal.
   */
  async _removeArmyTokensFromAllScenes(actorId: string, armyName: string): Promise<void> {
    const game = (globalThis as any).game;

    if (!game?.scenes) {
      logger.warn(`[ArmyActorBridge] Cannot remove tokens - scenes not available`);
      return;
    }

    let totalTokensRemoved = 0;

    for (const scene of game.scenes) {
      try {
        const tokensToDelete = scene.tokens.filter((token: any) => token.actorId === actorId);

        if (tokensToDelete.length > 0) {
          const tokenIds = tokensToDelete.map((token: any) => token.id);
          await scene.deleteEmbeddedDocuments('Token', tokenIds);
          totalTokensRemoved += tokenIds.length;
        }
      } catch (error) {
        logger.error(`[ArmyActorBridge] Failed to remove tokens from scene ${scene.name}:`, error);
      }
    }

    if (totalTokensRemoved > 0) {
      logger.info(`[ArmyActorBridge] Removed ${totalTokensRemoved} total token(s) for ${armyName} from all scenes`);
    }
  }

  /**
   * Read the canonical hex of every placed army from `army.position`.
   * No scene/token traversal — works regardless of what the GM is currently
   * viewing, and stays correct even if a recent move's animation has not
   * yet settled on the token doc. Armies with `position === null` (never
   * placed) are filtered out.
   */
  getArmyLocationsOnScene(): ArmyLocation[] {
    return armyLocationsFromKingdom(getKingdomData());
  }
}

export const armyActorBridge = new ArmyActorBridge();

/**
 * DoctrineAbilityService
 *
 * Manages automatic granting and removal of abilities on army actors
 * based on current doctrine state. Abilities are synced whenever
 * doctrine values change.
 */

import { kingdomData } from '../../stores/KingdomStore';
import { doctrineService } from './DoctrineService';
import { armyService } from '../army/index';
import { BulkArmyItemBatch } from '../army/BulkArmyService';
import {
  getActiveAbilities,
  getDoctrineAbilitySlug,
  DOCTRINE_ABILITY_SLUG_PREFIX,
  type DoctrineAbilityConfig,
} from '../../constants/doctrineAbilityMappings';
import type { Army } from '../../models/Army';
import type { DoctrineState } from '../../types/Doctrine';
import { logger } from '../../utils/Logger';
import { DOCTRINE_ABILITIES } from '../../data/abilities';

/**
 * DoctrineAbilityService class - singleton pattern
 */
class DoctrineAbilityService {
  private static instance: DoctrineAbilityService;

  static getInstance(): DoctrineAbilityService {
    if (!DoctrineAbilityService.instance) {
      DoctrineAbilityService.instance = new DoctrineAbilityService();
    }
    return DoctrineAbilityService.instance;
  }

  /**
   * Sync doctrine abilities to all player kingdom armies
   * Called after doctrine values change
   *
   * Collects every add/remove across every player army into one
   * `BulkArmyItemBatch` and dispatches once — saves up to (N armies ×
   * abilities-per-army) GM round-trips. Per-army logic still computes
   * the per-actor delta so deduplication and missing-item handling stay
   * the same.
   */
  async syncAbilitiesToAllArmies(doctrineState?: DoctrineState): Promise<void> {
    const kingdom = kingdomData.current;
    if (!kingdom?.armies) {
      logger.info('[DoctrineAbilityService] No armies to sync');
      return;
    }

    // Callers mid-apply pass the projected state so the sync reflects deltas
    // that have not committed yet (command-latency Wave A2).
    const state = doctrineState ?? doctrineService.getDoctrineState();
    const activeAbilities = getActiveAbilities(
      state.values,
      state.dominant,
      doctrineService.getTierForValue.bind(doctrineService),
      doctrineService.tierMeetsMinimum.bind(doctrineService)
    );

    logger.info(`[DoctrineAbilityService] Active abilities: ${activeAbilities.map(a => a.name).join(', ') || 'none'}`);

    // Get player kingdom armies only
    const playerArmies = kingdom.armies.filter((army: Army) =>
      army.ledBy === 'player' || army.ledBy === 'PLAYER_KINGDOM'
    );

    if (playerArmies.length === 0) {
      logger.info('[DoctrineAbilityService] No player armies to sync');
      return;
    }

    const batch = new BulkArmyItemBatch();
    for (const army of playerArmies) {
      if (!army.actorId) {
        logger.warn(`[DoctrineAbilityService] Army ${army.name} has no linked actor, skipping`);
        continue;
      }
      try {
        this.queueArmySync(army.actorId, activeAbilities, batch);
      } catch (error) {
        logger.error(`[DoctrineAbilityService] Failed to plan abilities for ${army.name}:`, error);
      }
    }
    await batch.dispatch();
  }

  /**
   * Sync doctrine abilities to a specific army actor.
   * Single-army convenience — queues the diff into a fresh batch and
   * dispatches inline. Multi-army callers should use
   * `syncAbilitiesToAllArmies` which shares one batch across armies.
   */
  async syncAbilitiesToArmy(actorId: string, activeAbilities?: DoctrineAbilityConfig[]): Promise<void> {
    const batch = new BulkArmyItemBatch();
    this.queueArmySync(actorId, activeAbilities, batch);
    await batch.dispatch();
  }

  /**
   * Plan the add/remove operations for one army actor and queue them
   * into the shared batch. Pure planning — no dispatches; the caller
   * dispatches once the batch covers every army.
   */
  private queueArmySync(
    actorId: string,
    activeAbilities: DoctrineAbilityConfig[] | undefined,
    batch: BulkArmyItemBatch,
  ): void {
    const game = (globalThis as any).game;
    const actor = game?.actors?.get(actorId);

    if (!actor) {
      logger.warn(`[DoctrineAbilityService] Actor not found: ${actorId}`);
      return;
    }

    // Get active abilities if not provided
    if (!activeAbilities) {
      const state = doctrineService.getDoctrineState();
      activeAbilities = getActiveAbilities(
        state.values,
        state.dominant,
        doctrineService.getTierForValue.bind(doctrineService),
        doctrineService.tierMeetsMinimum.bind(doctrineService)
      );
    }

    // Get current doctrine abilities on the actor
    const currentDoctrineItems = actor.items.filter((item: any) =>
      item.system?.slug?.startsWith(DOCTRINE_ABILITY_SLUG_PREFIX)
    );

    // STEP 1: Deduplicate - if multiple items have the same slug, keep only the first
    const slugToItems = new Map<string, any[]>();
    for (const item of currentDoctrineItems) {
      const slug = item.system.slug;
      if (!slugToItems.has(slug)) {
        slugToItems.set(slug, []);
      }
      slugToItems.get(slug)!.push(item);
    }

    // Remove duplicate items (keep only first of each slug)
    for (const [slug, items] of slugToItems.entries()) {
      if (items.length > 1) {
        logger.info(`[DoctrineAbilityService] Found ${items.length} duplicates of ${slug} on ${actor.name}, removing extras`);
        for (let i = 1; i < items.length; i++) {
          batch.removeItem(actorId, items[i].id);
        }
      }
    }

    // STEP 2: Normal sync logic - add/remove based on current doctrine state
    const currentSlugs = new Set(slugToItems.keys());
    const targetSlugs = new Set(activeAbilities.map(a => getDoctrineAbilitySlug(a.id)));

    // Remove abilities that should no longer be present
    const toRemove = Array.from(slugToItems.entries())
      .filter(([slug]) => !targetSlugs.has(slug))
      .map(([, items]) => items[0]);

    for (const item of toRemove) {
      logger.info(`[DoctrineAbilityService] Removing ${item.name} from ${actor.name}`);
      batch.removeItem(actorId, item.id);
    }

    // Add abilities that should be present but aren't
    const toAdd = activeAbilities.filter(ability =>
      !currentSlugs.has(getDoctrineAbilitySlug(ability.id))
    );

    for (const ability of toAdd) {
      const itemData = this.getAbilityItemData(ability);
      if (itemData) {
        logger.info(`[DoctrineAbilityService] Adding ${ability.name} to ${actor.name}`);
        batch.addItem(actorId, itemData);
      }
    }
  }

  /**
   * Get the item data for an ability from local TypeScript definitions
   */
  private getAbilityItemData(ability: DoctrineAbilityConfig): any | null {
    const data = DOCTRINE_ABILITIES[ability.sourceId];
    if (!data) {
      logger.error(`[DoctrineAbilityService] Ability not found: ${ability.sourceId}`);
      return null;
    }

    const itemData = structuredClone(data);
    itemData.system.slug = getDoctrineAbilitySlug(ability.id);

    // Add doctrine source to description
    const doctrineLabel = ability.doctrine.charAt(0).toUpperCase() + ability.doctrine.slice(1);
    const sourceNote = `<p><em>Granted by ${doctrineLabel} doctrine</em></p>`;
    itemData.system.description.value = sourceNote + itemData.system.description.value;

    return itemData;
  }

}

// Export singleton instance
export const doctrineAbilityService = DoctrineAbilityService.getInstance();

/**
 * Troop Ability Registry
 *
 * Every troop/army ability is one `export const` per file under the folders below.
 * They auto-discover via `import.meta.glob` — the first export per file satisfying
 * `isAbilityDef` is registered. Mirrors `src/pipelines/PipelineRegistry.ts`.
 */

import type { TroopAbilityDefinition } from './types';
import { logger } from '../../utils/Logger';

const modules = import.meta.glob<Record<string, unknown>>(
  [
    './core-attacks/*.ts',
    './war-actions/basic/*.ts',
    './war-actions/tactical/*.ts',
    './army-tactics/*.ts',
    './special-abilities/unique/*.ts',
    './special-abilities/official/*.ts',
    './creature-traits/*.ts',
  ],
  { eager: true }
);

function isAbilityDef(value: unknown): value is TroopAbilityDefinition {
  return (
    typeof value === 'object' &&
    value !== null &&
    typeof (value as Record<string, unknown>).slug === 'string' &&
    typeof (value as Record<string, unknown>).group === 'string' &&
    typeof (value as Record<string, unknown>).system === 'object'
  );
}

function extractAbilities(mods: Record<string, Record<string, unknown>>): TroopAbilityDefinition[] {
  const abilities: TroopAbilityDefinition[] = [];
  for (const [path, mod] of Object.entries(mods)) {
    const def = Object.values(mod).find(isAbilityDef);
    if (def) {
      abilities.push(def);
    } else {
      logger.warn(`[AbilityRegistry] No TroopAbilityDefinition export found in ${path}`);
    }
  }
  return abilities.sort((a, b) => a.slug.localeCompare(b.slug));
}

/** Every authored troop ability, sorted by slug for determinism. */
export const ALL_ABILITIES: TroopAbilityDefinition[] = extractAbilities(modules);

/** Every troop ability keyed by slug. */
export const TROOP_ABILITIES: Record<string, TroopAbilityDefinition> = Object.fromEntries(
  ALL_ABILITIES.map((a) => [a.slug, a])
);

/**
 * Shared read/write access to the troop-ability source files.
 *
 * Each ability is one `export const X: TroopAbilityDefinition = { …JSON… };` file.
 * The object literal is pure JSON, so it round-trips through JSON.parse / JSON.stringify.
 * Used by the pack build and the dev-only ability editor API.
 */

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const REGISTRY = path.join(ROOT, 'src/data/troopAbilities');
export const GROUP_DIRS = [
  'core-attacks',
  'war-actions/basic',
  'war-actions/tactical',
  'army-tactics',
  'special-abilities/unique',
  'special-abilities/official',
  'creature-traits'
];

export function listAbilityFiles() {
  const out = [];
  for (const dir of GROUP_DIRS) {
    const abs = path.join(REGISTRY, dir);
    if (!fs.existsSync(abs)) continue;
    for (const name of fs.readdirSync(abs).sort()) {
      if (!name.endsWith('.ts')) continue;
      out.push({ file: path.join(abs, name), dir });
    }
  }
  return out;
}

function literalSpan(text) {
  const start = text.indexOf('{', text.indexOf('export const'));
  const end = text.lastIndexOf('}');
  return { start, end };
}

export function readDefinition(file) {
  const text = fs.readFileSync(file, 'utf8');
  const { start, end } = literalSpan(text);
  return JSON.parse(text.slice(start, end + 1));
}

/** Rewrite only the object literal, preserving the import line, export name, and type annotation. */
export function writeDefinition(file, def) {
  const text = fs.readFileSync(file, 'utf8');
  const { start, end } = literalSpan(text);
  const next = text.slice(0, start) + JSON.stringify(def, null, 2) + text.slice(end + 1);
  fs.writeFileSync(file, next, 'utf8');
}

/** 16-char [A-Za-z0-9] Foundry id, deterministic from the seed so the compendium UUID is stable. */
export function stableDocId(seed) {
  const hash = crypto.createHash('sha1').update(seed).digest('base64');
  return hash.replace(/[^A-Za-z0-9]/g, '').slice(0, 16);
}

export function stableId(slug) {
  return stableDocId(`troop-ability:${slug}`);
}
